import mathfrom .units import to_unitdef eval_check(row: dict, check: dict, units_map: dict):    """    Evaluate a single check against a row (specimen).    Returns (status, rationale).    """    metric = check["metric"]    val = row.get(metric, None)    if val is None or (isinstance(val, float) and math.isnan(val)):        return "MISSING", f"{metric} missing"    from_u = units_map.get(metric)    target_u = check.get("unit", from_u)    if from_u and target_u and from_u != target_u:        try:            val = to_unit(val, from_u, target_u)        except Exception:            return "ERROR", f"unit conversion failed: {from_u}->{target_u}"    op = check["op"]    note = check.get("note", "")    if op == ">=":        margin = val - check["value"]; ok = val >= check["value"]    elif op == "<=":        margin = check["value"] - val; ok = val <= check["value"]    elif op == "between":        margin = min(val - check["min"], check["max"] - val); ok = check["min"] <= val <= check["max"]    elif op == "in_set":        ok = str(val) in set(map(str, check["set"])); margin = float("nan")    else:        return "ERROR", f"unknown op {op}"    status = "PASS" if ok else "FAIL"    rationale = f"{metric} {op} ({note}) | measured={val} {target_u or ''} | margin={'' if math.isnan(margin) else round(margin,3)}"    return status, rationale